import React from "react";
import ReactDOM from "react-dom/client";
import { BrowserRouter } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";
import App from "./App";

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(
  <BrowserRouter>
    <App />
  </BrowserRouter>
);

import React from "react";
import { Routes, Route, Navigate } from "react-router-dom";
import RecipesForum from "./pages/RecipesForum";
import CreateRecipe from "./pages/CreateRecipe";

export default function App() {
  return (
    <Routes>
      <Route path="/" element={<RecipesForum />} />
      <Route path="/recipe/create" element={<CreateRecipe />} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}

import axios from "axios";

// Base URL of the json-server mock API. CRA reads REACT_APP_* from .env at build time.
const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || "http://localhost:9999",
});

export default api;

import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Accordion, Form, Button, Container, Row, Col } from "react-bootstrap";
import api from "../api";

// Unique values, keeping first-seen order (so the filter lists are de-duplicated).
const uniq = (arr) => [...new Set(arr)];

export default function RecipesForum() {
  const navigate = useNavigate();
  const [recipes, setRecipes] = useState([]);
  const [search, setSearch] = useState("");
  const [selTags, setSelTags] = useState([]);
  const [selCuisines, setSelCuisines] = useState([]);
  const [selMeals, setSelMeals] = useState([]);

  // Load the whole list once; re-used to build the filter lists AND the accordion.
  useEffect(() => {
    api.get("/recipes").then((res) => setRecipes(res.data));
  }, []);

  // Filter lists come from ALL recipes (not the filtered view) and are de-duplicated.
  const allTags = uniq(recipes.flatMap((r) => r.tags || []));
  const allCuisines = uniq(recipes.map((r) => r.cuisine).filter(Boolean));
  const allMeals = uniq(recipes.flatMap((r) => r.mealType || []));

  const toggle = (value, list, setList) => {
    setList(list.includes(value) ? list.filter((x) => x !== value) : [...list, value]);
  };

  // What is shown is DERIVED from state — search (startsWith), the three facets (AND
  // between facets, "at least one" inside a facet), then sorted by rating descending.
  const shown = recipes
    .filter((r) => r.name.toLowerCase().startsWith(search.trim().toLowerCase()))
    .filter((r) => selTags.length === 0 || (r.tags || []).some((t) => selTags.includes(t)))
    .filter((r) => selCuisines.length === 0 || selCuisines.includes(r.cuisine))
    .filter((r) => selMeals.length === 0 || (r.mealType || []).some((m) => selMeals.includes(m)))
    .slice()
    .sort((a, b) => b.rating - a.rating);

  return (
    <Container className="py-4">
      <h1 id="app-title" className="text-center mb-4">RECIPES FORUM</h1>
      <Row>
        {/* LEFT: Tags */}
        <Col md={3} className="filter-tags">
          <h5>Tags</h5>
          {allTags.map((t) => (
            <Form.Check
              key={t}
              type="checkbox"
              id={"tag-" + t}
              value={t}
              label={t}
              checked={selTags.includes(t)}
              onChange={() => toggle(t, selTags, setSelTags)}
            />
          ))}
        </Col>

        {/* MIDDLE: search + Create Recipe + accordion */}
        <Col md={6}>
          <div className="d-flex justify-content-between align-items-start mb-3">
            <Form.Control
              id="search"
              type="text"
              placeholder="Enter Recipe Name to search ..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
            <Button
              id="btn-create-recipe"
              variant="primary"
              className="ms-2 text-nowrap"
              onClick={() => navigate("/recipe/create")}
            >
              Create Recipe
            </Button>
          </div>

          <Accordion>
            {shown.map((r) => (
              <Accordion.Item eventKey={String(r.id)} key={r.id}>
                <Accordion.Header>{r.name} - Rating: {r.rating}</Accordion.Header>
                <Accordion.Body>
                  <img
                    src={(process.env.PUBLIC_URL || "") + "/images/" + r.image}
                    alt={r.name}
                    style={{ width: 160, float: "right", marginLeft: 12 }}
                  />
                  <p>Preparation Time Minutes: {r.prepTimeMinutes}</p>
                  <p>Cook Time Minutes: {r.cookTimeMinutes}</p>
                  <p>Difficulty: {r.difficulty}</p>
                  <p>Cuisine: {r.cuisine}</p>
                  <p>Tags: {(r.tags || []).join("; ")}</p>
                  <p>Meal Types: {(r.mealType || []).join("; ")}</p>
                  <div>
                    <b>Ingredients</b>
                    <ul>
                      {(r.ingredients || []).map((x, i) => (
                        <li key={i}>{x}</li>
                      ))}
                    </ul>
                  </div>
                  <div>
                    <b>Instructions</b>
                    <ul>
                      {(r.instructions || []).map((x, i) => (
                        <li key={i}>{x}</li>
                      ))}
                    </ul>
                  </div>
                </Accordion.Body>
              </Accordion.Item>
            ))}
          </Accordion>
        </Col>

        {/* RIGHT: Cuisine + Meal Type */}
        <Col md={3}>
          <div className="filter-cuisine">
            <h5>Cuisine</h5>
            {allCuisines.map((c) => (
              <Form.Check
                key={c}
                type="checkbox"
                id={"cuisine-" + c}
                value={c}
                label={c}
                checked={selCuisines.includes(c)}
                onChange={() => toggle(c, selCuisines, setSelCuisines)}
              />
            ))}
          </div>
          <div className="filter-mealtype mt-3">
            <h5>Meal Type</h5>
            {allMeals.map((m) => (
              <Form.Check
                key={m}
                type="checkbox"
                id={"meal-" + m}
                value={m}
                label={m}
                checked={selMeals.includes(m)}
                onChange={() => toggle(m, selMeals, setSelMeals)}
              />
            ))}
          </div>
        </Col>
      </Row>
    </Container>
  );
}

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Form, Button, Container } from "react-bootstrap";
import api from "../api";

// "a; b; c" -> ["a","b","c"] (trimmed, empties dropped)
const splitList = (s) => s.split(";").map((x) => x.trim()).filter(Boolean);

export default function CreateRecipe() {
  const navigate = useNavigate();
  const [name, setName] = useState("");
  const [ingredients, setIngredients] = useState("");
  const [instructions, setInstructions] = useState("");
  const [prep, setPrep] = useState(0);
  const [cook, setCook] = useState(0);
  const [cuisine, setCuisine] = useState("");
  const [difficulty, setDifficulty] = useState("");
  const [tags, setTags] = useState("");
  const [meals, setMeals] = useState("");
  const [error, setError] = useState("");

  const onSave = async (e) => {
    e.preventDefault();
    if (!name.trim()) {
      setError("Recipe Name is required");
      return; // do NOT submit
    }
    setError("");
    const newRecipe = {
      name: name.trim(),
      ingredients: splitList(ingredients),
      instructions: splitList(instructions),
      prepTimeMinutes: Number(prep) || 0,
      cookTimeMinutes: Number(cook) || 0,
      cuisine: cuisine.trim(),
      difficulty: difficulty.trim(),
      tags: splitList(tags),
      mealType: splitList(meals),
      image: "thumbnail.png", // no rating on a brand-new recipe
    };
    await api.post("/recipes", newRecipe);
    alert("Create new Recipe success!");
    navigate("/"); // back to the list, which reloads from the server
  };

  return (
    <Container className="py-4" style={{ maxWidth: 640 }}>
      <h1 id="form-title" className="mb-4">Create A New Recipe</h1>
      <Form onSubmit={onSave}>
        <Form.Group className="mb-3">
          <Form.Label>Recipe Name <span className="text-danger">*</span></Form.Label>
          <Form.Control id="name" value={name} onChange={(e) => setName(e.target.value)} />
          {error && <div id="name-error" className="text-danger mt-1">{error}</div>}
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Ingredients</Form.Label>
          <Form.Control id="ingredients" value={ingredients} onChange={(e) => setIngredients(e.target.value)} placeholder="Separate ingredients with ;" />
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Instructions</Form.Label>
          <Form.Control id="instructions" value={instructions} onChange={(e) => setInstructions(e.target.value)} placeholder="Separate instructions with ;" />
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Preparation Time Minutes</Form.Label>
          <Form.Control id="prep" type="number" value={prep} onChange={(e) => setPrep(e.target.value)} />
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Cook Time Minutes</Form.Label>
          <Form.Control id="cook" type="number" value={cook} onChange={(e) => setCook(e.target.value)} />
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Cuisine</Form.Label>
          <Form.Control id="cuisine" value={cuisine} onChange={(e) => setCuisine(e.target.value)} />
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Difficulty</Form.Label>
          <Form.Control id="difficulty" value={difficulty} onChange={(e) => setDifficulty(e.target.value)} />
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Tags</Form.Label>
          <Form.Control id="tags" value={tags} onChange={(e) => setTags(e.target.value)} placeholder="Separate tags with ;" />
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Meal Types</Form.Label>
          <Form.Control id="mealTypes" value={meals} onChange={(e) => setMeals(e.target.value)} placeholder="Separate meal types with ;" />
        </Form.Group>

        <Button id="btn-save" type="submit" variant="success">Save</Button>
      </Form>
    </Container>
  );
}
